import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"Privacy and data","description":"","frontmatter":{},"headers":[],"relativePath":"reference/privacy.md","filePath":"reference/privacy.md","lastUpdated":1793128542000}'),i={name:"reference/privacy.md"};function n(s,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="privacy-and-data" tabindex="-1">Privacy and data <a class="header-anchor" href="#privacy-and-data" aria-label="Permalink to &quot;Privacy and data&quot;">​</a></h1><p>This page explains what MeetCue sends to which provider, what it keeps on your computer, and what it never collects. MeetCue has no server of its own: everything runs on your computer and talks directly to the providers you chose with your own keys.</p><h2 id="what-goes-to-your-speech-recognition-provider" tabindex="-1">What goes to your speech recognition provider <a class="header-anchor" href="#what-goes-to-your-speech-recognition-provider" aria-label="Permalink to &quot;What goes to your speech recognition provider&quot;">​</a></h2><ul><li>Audio from your microphone and from system sound while listening is on, converted to 16 kHz mono. Silence is not sent, except about 0.3 s just before speech starts so the first word isn&#39;t cut off, and up to about a second after it so the recognizer can tell the sentence ended.</li><li>Terms from your briefing material, as recognition hints.</li><li>In practice mode with <strong>Speech-to-text for the questions</strong> off, the other side&#39;s audio isn&#39;t sent.</li></ul><h2 id="what-goes-to-your-language-model-provider" tabindex="-1">What goes to your language model provider <a class="header-anchor" href="#what-goes-to-your-language-model-provider" aria-label="Permalink to &quot;What goes to your language model provider&quot;">​</a></h2><ul><li>For detection: the recognised sentence and a few sentences of context.</li><li>For hints: the question, recent conversation, your role, and a short excerpt of your briefing material.</li><li>In practice mode: questions, your recognised answers, reference answers for feedback, and subtitle lines to classify.</li><li>During the latency probe: a short built-in sample transcript.</li></ul><h2 id="price-lookups" tabindex="-1">Price lookups <a class="header-anchor" href="#price-lookups" aria-label="Permalink to &quot;Price lookups&quot;">​</a></h2><p>To estimate costs for your usage and budget, MeetCue reads the public pricing pages of Anthropic, Soniox and Deepgram and the <a href="/meetcue/reference/pricing">price reference</a> on this site, at start-up. These are ordinary page downloads: no key, account or meeting content is sent.</p><p>Each provider&#39;s own privacy policy and data retention terms apply to what you send them. Check them before using MeetCue in confidential meetings.</p><h2 id="what-stays-on-your-computer" tabindex="-1">What stays on your computer <a class="header-anchor" href="#what-stays-on-your-computer" aria-label="Permalink to &quot;What stays on your computer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Location</th></tr></thead><tbody><tr><td>API keys</td><td>Windows Credential Manager, entries named <code>MeetCue</code></td></tr><tr><td>Settings, role and extracted briefing text</td><td><code>settings.json</code> in the settings folder</td></tr><tr><td>Latency results</td><td><code>latency-history.json</code></td></tr><tr><td>Usage and cost per call (no content)</td><td><code>usage.jsonl</code></td></tr><tr><td>Logs, kept 7 days, without transcripts unless debug logging is on (the last lines are also shown in <strong>Settings › Diagnostics › Activity log</strong>)</td><td><code>logs\\</code></td></tr><tr><td>Last price list, for offline use</td><td><code>pricing.json</code></td></tr><tr><td>Practice reports</td><td><code>practice\\</code></td></tr></tbody></table><p>See <a href="/meetcue/reference/settings#where-settings-are-stored">Settings</a> for the folder location. Audio is never saved to disk.</p><h2 id="what-meetcue-never-does" tabindex="-1">What MeetCue never does <a class="header-anchor" href="#what-meetcue-never-does" aria-label="Permalink to &quot;What MeetCue never does&quot;">​</a></h2><ul><li>No telemetry, usage statistics or crash reports are collected.</li><li>API keys are never sent to the interface, written to files or logged.</li><li>Diagnostics exports never include keys, transcripts, briefing material or practice records.</li><li>Nothing is sent anywhere while listening is paused, except a latency probe you start yourself.</li></ul><h2 id="delete-your-data" tabindex="-1">Delete your data <a class="header-anchor" href="#delete-your-data" aria-label="Permalink to &quot;Delete your data&quot;">​</a></h2><p><strong>Settings › General › Erase all data</strong> does it in one step: type the confirmation word and MeetCue removes its API keys from Credential Manager, deletes everything in the settings folder listed above, clears the interface&#39;s own browser storage, turns off start with Windows, and restarts as if newly installed.</p><p>To remove MeetCue entirely instead:</p><ol><li>Uninstall with <code>scoop uninstall meetcue --purge</code> to remove the settings folder.</li><li>Remove the <code>MeetCue</code> entries in <strong>Credential Manager › Windows Credentials</strong>.</li></ol><p>Either way, ask your providers to delete data they retained, according to their policies.</p>',19)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
